        #region Mutagen
        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(ICreatureGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            if (obj.Model is {} ModelItems)
            {
                foreach (var item in ModelItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            foreach (var item in obj.ActorEffects)
            {
                yield return FormLinkInformation.Factory(item);
            }
            if (FormLinkInformation.TryFactory(obj.ObjectEffect, out var ObjectEffectInfo))
            {
                yield return ObjectEffectInfo;
            }
            if (obj.Destructible is {} DestructibleItems)
            {
                foreach (var item in DestructibleItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (FormLinkInformation.TryFactory(obj.Script, out var ScriptInfo))
            {
                yield return ScriptInfo;
            }
            if (FormLinkInformation.TryFactory(obj.DeathItem, out var DeathItemInfo))
            {
                yield return DeathItemInfo;
            }
            if (FormLinkInformation.TryFactory(obj.Voice, out var VoiceInfo))
            {
                yield return VoiceInfo;
            }
            if (FormLinkInformation.TryFactory(obj.Template, out var TemplateInfo))
            {
                yield return TemplateInfo;
            }
            foreach (var item in obj.Items.WhereCastable<IContainerEntryGetter, IFormLinkContainerGetter>()
                .SelectMany((f) => f.EnumerateFormLinks(iterateNestedRecords)))
            {
                yield return FormLinkInformation.Factory(item);
            }
            foreach (var item in obj.Packages)
            {
                yield return FormLinkInformation.Factory(item);
            }
            if (FormLinkInformation.TryFactory(obj.CombatStyle, out var CombatStyleInfo))
            {
                yield return CombatStyleInfo;
            }
            if (FormLinkInformation.TryFactory(obj.BodyPartData, out var BodyPartDataInfo))
            {
                yield return BodyPartDataInfo;
            }
            if (FormLinkInformation.TryFactory(obj.InheritsSoundsFrom, out var InheritsSoundsFromInfo))
            {
                yield return InheritsSoundsFromInfo;
            }
            if (FormLinkInformation.TryFactory(obj.SoundItem, out var SoundItemInfo))
            {
                yield return SoundItemInfo;
            }
            if (FormLinkInformation.TryFactory(obj.ImpactDataset, out var ImpactDatasetInfo))
            {
                yield return ImpactDatasetInfo;
            }
            if (FormLinkInformation.TryFactory(obj.MeleeWeaponList, out var MeleeWeaponListInfo))
            {
                yield return MeleeWeaponListInfo;
            }
            yield break;
        }
        
        #region Duplicate
        public Creature Duplicate(
            ICreatureGetter item,
            FormKey formKey,
            TranslationCrystal? copyMask)
        {
            var newRec = new Creature(formKey, default(Fallout3Release));
            newRec.DeepCopyIn(item, default(ErrorMaskBuilder?), copyMask);
            return newRec;
        }
        
